type MarketPlayer={id:string;name:string;position:string;team:string};
const normalizedName=(name:string)=>name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
const is2027FreeAgent=(name:string)=>upcomingFreeAgents.some(f=>normalizedName(f.name)===normalizedName(name)&&!f.option);
const isPitcher=(position:string)=>['P','SP','RP','CP','CL'].includes(position.toUpperCase());
const rosterSelection=(players:Player[])=>{const pitchers=players.filter(p=>isPitcher(p.position)).slice(0,13);const hitters=players.filter(p=>!isPitcher(p.position)).slice(0,13);return [...pitchers,...hitters].map(p=>p.id)};
const toPlayer=(p:MarketPlayer,salary=0):Player=>({...p,age:0,ovr:0,war:0,salary,years:0});

type TradeSide='sendMlb'|'receiveMlb'|'sendProspects'|'receiveProspects';
type TradeBuilderProps={mineName:string;theirsName:string;minePlayers:Player[];theirPlayers:Player[];mineProspects:Prospect[];theirProspects:Prospect[];sendMlb:string[];receiveMlb:string[];sendProspects:string[];receiveProspects:string[];setSendMlb:React.Dispatch<React.SetStateAction<string[]>>;setReceiveMlb:React.Dispatch<React.SetStateAction<string[]>>;setSendProspects:React.Dispatch<React.SetStateAction<string[]>>;setReceiveProspects:React.Dispatch<React.SetStateAction<string[]>>};
function TradeBuilder(p:TradeBuilderProps){
 const [search,setSearch]=useState({mine:'',theirs:''});
 const [category,setCategory]=useState({mine:'all',theirs:'all'});
 const [dragOver,setDragOver]=useState<'mine'|'theirs'|null>(null);
 const sides:{key:'mine'|'theirs';name:string;players:Player[];prospects:Prospect[];mlb:TradeSide;farm:TradeSide}[]=[{key:'mine',name:p.mineName,players:p.minePlayers,prospects:p.mineProspects,mlb:'sendMlb',farm:'sendProspects'},{key:'theirs',name:p.theirsName,players:p.theirPlayers,prospects:p.theirProspects,mlb:'receiveMlb',farm:'receiveProspects'}];
 const selection=(key:TradeSide)=>p[key];
 const change=(key:TradeSide,fn:(a:string[])=>string[])=>{const setters={sendMlb:p.setSendMlb,receiveMlb:p.setReceiveMlb,sendProspects:p.setSendProspects,receiveProspects:p.setReceiveProspects};setters[key](fn)};
 const add=(key:TradeSide,id:string)=>change(key,a=>a.includes(id)?a:[...a,id]);
 const remove=(key:TradeSide,id:string)=>change(key,a=>a.filter(x=>x!==id));
 const startDrag=(e:React.DragEvent<HTMLElement>,key:TradeSide,id:string)=>{e.dataTransfer.setData('text/plain',JSON.stringify({key,id}));e.dataTransfer.effectAllowed='copy'};
 const drop=(e:React.DragEvent<HTMLElement>,side:'mine'|'theirs')=>{e.preventDefault();setDragOver(null);try{const payload=JSON.parse(e.dataTransfer.getData('text/plain')) as {key:TradeSide;id:string};const valid=side==='mine'?['sendMlb','sendProspects']:['receiveMlb','receiveProspects'];if(valid.includes(payload.key))add(payload.key,payload.id)}catch{}};
 return <div className="trade-board">{sides.map(side=>{const entries=[...side.players.map(x=>({...x,kind:'MLB' as const,key:side.mlb})),...side.prospects.map(x=>({...x,kind:'PROSPECT' as const,key:side.farm}))];const picked=entries.filter(x=>selection(x.key).includes(String(x.id)));const available=entries.filter(x=>!selection(x.key).includes(String(x.id))&&(category[side.key]==='all'||(category[side.key]==='mlb'?x.kind==='MLB':x.kind==='PROSPECT'))&&x.name.toLowerCase().includes(search[side.key].toLowerCase()));return <section className="trade-column" key={side.key}><div className="trade-column-title"><span>{side.key==='mine'?'YOU SEND':'YOU RECEIVE'}</span><h3>{side.name}</h3></div><div className={`trade-dropzone ${dragOver===side.key?'drag-over':''}`} onDragOver={e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';setDragOver(side.key)}} onDragLeave={e=>{if(!e.currentTarget.contains(e.relatedTarget as Node))setDragOver(null)}} onDrop={e=>drop(e,side.key)} aria-label={`${side.name} trade package`}><div className="trade-drop-title">TRADE PACKAGE <span>{picked.length} SELECTED</span></div>{picked.length===0?<p className="trade-drop-hint">Drag players here or click + below</p>:picked.map(x=><div className="trade-picked" key={`${x.key}-${x.id}`}><div><strong>{x.name}</strong><small>{x.position} · {x.kind}</small></div><button type="button" aria-label={`Remove ${x.name}`} onClick={()=>remove(x.key,String(x.id))}><X size={15}/></button></div>)}</div><div className="trade-pool"><div className="trade-pool-head">AVAILABLE PLAYERS <span>{available.length}</span></div><input className="trade-search" aria-label={`Search ${side.name} players`} placeholder="Search players..." value={search[side.key]} onChange={e=>setSearch(v=>({...v,[side.key]:e.target.value}))}/><div className="trade-filters">{(['all','mlb','prospects'] as const).map(c=><button key={c} type="button" className={category[side.key]===c?'selected':''} onClick={()=>setCategory(v=>({...v,[side.key]:c}))}>{c==='all'?'ALL':c==='mlb'?'MLB':'PROSPECTS'}</button>)}</div><div className="trade-player-list">{available.length===0?<p className="trade-drop-hint">No players found.</p>:available.map(x=><button className="trade-player" type="button" draggable onDragStart={e=>startDrag(e,x.key,String(x.id))} onClick={()=>add(x.key,String(x.id))} key={`${x.key}-${x.id}`} title={`Add ${x.name} to trade`}><span className="trade-drag-handle">⠿</span><span className="trade-player-name"><strong>{x.name}</strong><small>{x.position} · {x.kind}</small></span><Plus size={16}/></button>)}</div></div></section>})}</div>
}

