 useEffect(()=>{if(!Object.keys(playerRatings).length)return;setSave(prev=>prev?{...prev,roster:prev.roster.map(p=>{const rating=playerRatings[p.id];return rating?{...p,ovr:rating.rating,ratingSource:rating.source,statSummary:rating.summary,statSeason:rating.season}:p})}:prev)},[playerRatings]);
