 function alertMsg(msg:string){setNotice(msg);window.setTimeout(()=>setNotice(''),5000)}
 function tradeValue(player:Player){const rating=playerRatings[player.id]?.rating??player.ovr??65;const salary=salaryFor(player)??0;return Math.max(4,Math.round((rating-40)*1.35-Math.max(0,salary-18)*0.55));}
 function acceptCounter(){if(!counterProposal)return;setSendMlb(counterProposal.sendMlb);setReceiveMlb(counterProposal.receiveMlb);setSendProspects(counterProposal.sendProspects);setReceiveProspects(counterProposal.receiveProspects);setTradeDecision('counter');setTradeMessage('Counteroffer loaded into the deal builder. Review the updated packages, then submit again.');setCounterProposal(null);}
 function evaluateTrade(){
  if(!save||!season||!['offseason','deadline'].includes(season.phase)){setTradeMessage('Trading is closed outside the offseason and trade deadline.');return;}
  if(trade.opponent===save.team){setTradeMessage('Select another franchise.');return;}
  const mine=save.roster.filter(p=>sendMlb.includes(p.id));
  const theirs=opposing.filter(p=>receiveMlb.includes(p.id));
  const outgoing=(save.prospects||[]).filter(p=>sendProspects.includes(p.id));
  const incoming=[...opponentProspects.filter(p=>!teamTradeChanges[trade.opponent]?.removedProspects.includes(p.id)),...(teamTradeChanges[trade.opponent]?.addedProspects||[])].filter(p=>receiveProspects.includes(p.id));
  if(!(mine.length+outgoing.length)||!(theirs.length+incoming.length)){setTradeMessage('Include at least one player or prospect from each team.');return;}
  const sent=[...mine.map(p=>p.name),...outgoing.map(p=>p.name+' (MiLB)')];
  const received=[...theirs.map(p=>p.name),...incoming.map(p=>p.name+' (MiLB)')];
  const sentValue=mine.reduce((n,p)=>n+tradeValue(p),0)+outgoing.length*17;
  const receivedValue=theirs.reduce((n,p)=>n+tradeValue(p),0)+incoming.length*17;
  // A deterministic simulated opposing GM: asks for at least 85% of the value they give up.
  if(sentValue<receivedValue*0.85){
    const missing=Math.ceil(receivedValue*0.85-sentValue);
    const availableMlb=save.roster.filter(p=>!sendMlb.includes(p.id)).sort((a,b)=>Math.abs(tradeValue(a)-missing)-Math.abs(tradeValue(b)-missing));
    const availableProspects=(save.prospects||[]).filter(p=>!sendProspects.includes(p.id));
    let proposal:null|{sendMlb:string[];receiveMlb:string[];sendProspects:string[];receiveProspects:string[];description:string}=null;
    const extra=availableMlb.find(p=>tradeValue(p)>=missing);
    if(extra)proposal={sendMlb:[...sendMlb,extra.id],receiveMlb:[...receiveMlb],sendProspects:[...sendProspects],receiveProspects:[...receiveProspects],description:`Add ${extra.name} to your outgoing package.`};
    else if(availableProspects.length&&missing<=17)proposal={sendMlb:[...sendMlb],receiveMlb:[...receiveMlb],sendProspects:[...sendProspects,availableProspects[0].id],receiveProspects:[...receiveProspects],description:`Add prospect ${availableProspects[0].name} to your outgoing package.`};
    else if(theirs.length+incoming.length>1){const last=theirs.length?theirs[theirs.length-1]:null;const prospect=last?null:incoming[incoming.length-1];proposal={sendMlb:[...sendMlb],receiveMlb:last?receiveMlb.filter(id=>id!==last.id):[...receiveMlb],sendProspects:[...sendProspects],receiveProspects:prospect?receiveProspects.filter(id=>id!==prospect.id):[...receiveProspects],description:`Remove ${last?.name??prospect?.name} from the return package.`};}
    setCounterProposal(proposal);setTradeDecision('rejected');setTradeMessage(`${teamName(trade.opponent)} declined your offer. They estimate the package is short by ${missing} trade-value points.${proposal?' They have proposed a counteroffer below.':' Add more value to your package and try again.'}`);
    const rejected={id:`T-${Date.now()}`,sent:sent.join(', '),target:received.join(', '),status:'Rejected' as const,reason:`Declined by ${teamName(trade.opponent)} · simulated valuation ${sentValue} offered vs ${receivedValue} requested.`};
    setSave(prev=>prev?{...prev,trades:[rejected,...prev.trades]}:prev);
    return;
  }
  // Record both sides of the deal, including opponent ownership, in the saved franchise.
  setTeamTradeChanges(prev=>{const old=prev[trade.opponent]||{added:[],removed:[],addedProspects:[],removedProspects:[]};return {...prev,[trade.opponent]:{
    added:[...old.added.filter(p=>!receiveMlb.includes(p.id)&&!mine.some(m=>m.id===p.id)),...mine.map(p=>({...p,team:trade.opponent}))],
    removed:[...new Set([...old.removed,...receiveMlb])],
    addedProspects:[...old.addedProspects.filter(p=>!receiveProspects.includes(p.id)&&!outgoing.some(m=>m.id===p.id)),...outgoing.map(p=>({...p,team:trade.opponent,organization:trade.opponent}))],
    removedProspects:[...new Set([...old.removedProspects,...receiveProspects])]
  }}});
  setActiveIds(prev=>prev.filter(id=>!sendMlb.includes(id)));
  setCounterProposal(null);setTradeDecision('accepted');
  const entry={id:`T-${Date.now()}`,sent:sent.join(', '),target:received.join(', '),status:'Accepted' as const,reason:`Sandbox trade with ${teamName(trade.opponent)} · ${new Date().toLocaleDateString()}.`,sentProspects:outgoing.map(p=>p.id),receivedProspects:incoming.map(p=>p.id)};
  setSave(prev=>prev?{...prev,roster:[...prev.roster.filter(p=>!sendMlb.includes(p.id)),...theirs.map(p=>({...p,team:prev.team}))],prospects:[...(prev.prospects||[]).filter(p=>!sendProspects.includes(p.id)),...incoming.map(p=>({...p,team:prev.team,organization:prev.team}))],prospectsTradedAway:(prev.prospectsTradedAway||0)+outgoing.length,prospectsAcquired:(prev.prospectsAcquired||0)+incoming.length,trades:[entry,...prev.trades]}:prev);
  setTradeMessage(`Trade saved: sent ${sent.join(', ')}; acquired ${received.join(', ')}.`);
  setSendMlb([]);setReceiveMlb([]);setSendProspects([]);setReceiveProspects([]);
 }
