 async function addMarketPlayer(){const id=marketId.trim();if(!/^\d+$/.test(id)){setMarketError('Enter a numeric MLB player ID.');return;}setMarketError('');try{const res=await fetch(`/api/mlb/player?id=${encodeURIComponent(id)}`);const d=await res.json();if(!res.ok)throw new Error(d.error||'Player lookup failed');if(save?.roster.some(p=>p.id===id)||market.some(p=>p.id===id))throw new Error('Player is already in your roster or free-agent pool.');setMarket(prev=>[{id,name:d.name,position:d.position,team:'FA'},...prev]);setMarketId('');alertMsg(`${d.name} added to your simulation free-agent pool.`)}catch(e){setMarketError(e instanceof Error?e.message:'Lookup failed')}}
